# Calculator checks: known-truth simulations, scenarios, validation and the reverse conversion
source("R/helpers.R"); source("R/conv_skew_null.R"); source("R/conv_helpers.R")
ok <- function(c, m) if (!isTRUE(c)) stop(m, call. = FALSE) else cat("OK  ", m, "\n")
set.seed(11); x <- rnorm(5000, 50, 10); q <- unname(quantile(x, c(.25, .5, .75)))
r <- conv_to_meansd(5000, q1 = q[1], med = q[2], q3 = q[3])
ok(all(abs(r$mean - 50) < 0.7) && all(abs(r$sd - 10) < 0.7), "S2 (quartiles) recovers mean and SD of a normal sample")
r <- conv_to_meansd(5000, min = min(x), med = q[2], max = max(x))
ok(all(abs(r$mean - 50) < 1.5) && all(abs(r$sd - 10) < 1.5), "S1 (range) recovers mean and SD of a normal sample")
y <- rlnorm(5000, 3, 0.7); qy <- unname(quantile(y, c(.25, .5, .75)))
r <- conv_to_meansd(5000, q1 = qy[1], med = qy[2], q3 = qy[3])
ok(abs(r$mean[r$method == CONV_METHODS[["mln"]]] - mean(y)) / mean(y) < 0.05, "lognormal method recovers the mean of skewed data")
ok(abs(r$mean[1] - mean(y)) > abs(r$mean[r$method == CONV_METHODS[["mln"]]] - mean(y)), "Wan is worse than the lognormal method on skewed data")
ok(conv_skew(q1 = qy[1], med = qy[2], q3 = qy[3], n = 5000)$skewed && !conv_skew(q1 = q[1], med = q[2], q3 = q[3], n = 5000)$skewed, "skewness flag")
ok(!is.null(conv_check(10, q1 = 5, med = 4, q3 = 6)) && !is.null(conv_check(NA, med = 4, q1 = 1, q3 = 6)) && is.null(conv_check(30, q1 = 1, med = 4, q3 = 6)), "validation")
b <- conv_to_median(50, 10); ok(abs(b$q1[1] - 43.255) < 0.01 && abs(b$iqr[1] - 13.49) < 0.01, "normal reverse conversion")
ln <- conv_to_median(mean(y), sd(y)); ok(abs(ln$median[2] - median(y)) / median(y) < 0.1, "lognormal reverse conversion")

# ---- upgrades: other conversions, table rows, pairing, the calibrated skewness p-value
source("R/km_helpers.R"); source("R/conv_module.R")
ok(abs(conv_se_to_sd(2, 25) - 10) < 1e-12, "SE to SD")
ok(abs(conv_ci_to_sd(40, 60, 100) - 200 / (2 * qt(0.975, 99))) < 1e-9, "95% CI to SD uses the t distribution")
set.seed(5); a <- rnorm(40, 10, 3); b <- rnorm(55, 14, 5); cmb <- conv_combine(40, mean(a), sd(a), 55, mean(b), sd(b))
ok(abs(cmb$mean - mean(c(a, b))) < 1e-10 && abs(cmb$sd - sd(c(a, b))) < 1e-10 && cmb$n == 95, "combining two groups equals the mean and SD of the pooled raw data")
r <- conv_row(50, mean = 5, sd = 2); ok(r$source == "reported" && r$mean == 5 && r$sd == 2, "reported mean and SD are kept")
r <- conv_row(50, q1 = 4, med = 5, q3 = 6.1, method = "wan"); ok(grepl("Wan", r$source) && is.finite(r$sd), "chosen method is used")
r <- conv_row(80, min = 1, q1 = 3, med = 5, q3 = 12, max = 60); ok(grepl("Box-Cox", r$source) && grepl("asymmetric", r$note), "auto picks a skewed-data method for asymmetric summaries")
r <- conv_row(80, q1 = 40, med = 50, q3 = 60.2); ok(grepl("Wan", r$source), "auto picks Wan and Luo for symmetric summaries")
r <- conv_row(NA, q1 = 4, med = 5, q3 = 6); ok(r$source == "error" && nzchar(r$note), "a row without n is an error, not a guess")
r <- conv_row(50, mean = 5, sd = 0); ok(r$source == "error", "an SD of zero is an error")
tx <- "study\tgroup\tn\tmean\tsd\tmin\tq1\tmedian\tq3\tmax\nA\ttreatment\t60\t\t\t\t45\t52\t60\t\nA\tcontrol\t58\t55,1\t12.3\t\t\t\t\t\nB\ttreatment\t80\t\t\t30\t\t55\t\t90\nB\tcontrol\t82\t\t\t28\t\t61\t\t97\nC\ttreatment\t45\t50.2\t9.8\t\t\t\t\t\n"
bt <- conv_read_batch(tx); ok(nrow(bt$data) == 5 && bt$data$mean[2] == 55.1 && is.na(bt$data$mean[1]), "pasted table is read, decimal commas accepted")
res <- conv_batch_run(bt$data, "auto"); ok(nrow(res) == 5 && all(res$source != "error"), "every row of the table is converted")
pr <- conv_pairs(res); ok(nrow(pr$data) == 2 && length(pr$skipped) == 1 && grepl("^C:", pr$skipped), "pairs complete studies and reports the incomplete one")
ok(all(c("study_id", "mean_tx", "sd_tx", "n_tx", "mean_ctrl", "sd_ctrl", "n_ctrl") %in% names(pr$data)), "paired table has the continuous forest-plot columns")
ok(!is.null(conv_read_batch("nonsense without structure")$error) || is.data.frame(conv_read_batch("nonsense without structure")$data), "garbage input does not crash")
# the p-value: normal data gives large p, strongly skewed gives small p
set.seed(8); qn <- unname(quantile(rnorm(300), c(.25, .5, .75))); qs <- unname(quantile(rlnorm(300, 0, 0.9), c(.25, .5, .75)))
ok(conv_skew(q1 = qn[1], med = qn[2], q3 = qn[3], n = 300)$p > 0.1 && conv_skew(q1 = qs[1], med = qs[2], q3 = qs[3], n = 300)$p < 0.05, "skewness p-value separates normal from skewed data")
ok(conv_skew(min = 1, med = 5, max = 90, n = 50)$skewed, "range-based skewness check")
